-- Synthetic teaching material only. Once-only migration preserves all existing content.
INSERT INTO resources(id,organization_id,title,description,level,skill,topic,tags,content,status,kind,updated_at)
SELECT 'resource-introductions',id,'Introduce yourself','Modelo breve para presentarse con un personaje ficticio.','Beginner','conversación','Greetings','["saludos","demostración"]','Hello! My name is Sunny. What is your name? Usa un personaje imaginario para practicar.','published','text',strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM organizations WHERE id='org-demo';
INSERT INTO lessons(id,program_id,status,content,unit_id,position,updated_at)
SELECT 'greetings-and-introductions','exploradores','draft',
'{"id":"greetings-and-introductions","title":"Greetings and Introductions","program":"Greetings","unitId":"unit-org-demo","duration":20,"objective":"Saludar y presentarse con frases sencillas en inglés.","materials":["Un títere o personaje de papel"],"reflection":"¿Qué saludo usarías al llegar a clase?","publishedAt":"","shareCode":"GREETINGS","activities":[{"id":"greet-text","type":"text","position":0,"title":"Say hello","minutes":5,"instructions":"Saluda con la mano y di Hello! Imagina que eres un personaje de una historia."},{"id":"greet-resource","type":"resource","position":1,"title":"Meet Sunny","minutes":10,"instructions":"Lee el modelo y practica con un compañero. Usa un nombre imaginario.","resourceId":"resource-introductions"},{"id":"greet-question","type":"question","position":2,"title":"Choose a greeting","minutes":5,"instructions":"¿Qué dices para saludar?","options":["Hello!","Goodbye!","Thank you!"],"answer":0}]}',
'unit-org-demo',(SELECT count(*) FROM lessons WHERE unit_id='unit-org-demo'),strftime('%Y-%m-%dT%H:%M:%fZ','now')
WHERE EXISTS(SELECT 1 FROM organizations WHERE id='org-demo');
UPDATE lessons SET status='published',revision=1,published_version=1,published_content=json_set(content,'$.publishedAt',updated_at,'$.revision',1,'$.resources',json((SELECT json_group_array(json_object('id',id,'title',title,'description',description,'level',level,'skill',skill,'topic',topic,'tags',json(tags),'content',content,'status',status,'kind',kind)) FROM resources WHERE id='resource-introductions'))) WHERE id='greetings-and-introductions';
